-- Additive workspace extensions; preserve all existing rows and delivery state.
CREATE UNIQUE INDEX notes_id_owner ON notes(id,user_id);
CREATE TABLE tags(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 80),color TEXT NOT NULL CHECK(length(color)=7),UNIQUE(id,user_id));
CREATE INDEX tags_updated ON tags(updated_at,id);
CREATE TRIGGER sync_tags_insert AFTER INSERT ON tags WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('tags',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'name',NEW.name,'color',NEW.color),(SELECT revision FROM native_sync_meta WHERE entity_table='tags' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='tags' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_tags_update AFTER UPDATE ON tags WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('tags',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'name',NEW.name,'color',NEW.color),(SELECT revision FROM native_sync_meta WHERE entity_table='tags' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='tags' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_tags_delete AFTER DELETE ON tags WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('tags',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='tags' AND id=OLD.id),OLD.remote_updated_at); END;
CREATE TABLE note_tags(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),note_id TEXT NOT NULL,tag_id TEXT NOT NULL,UNIQUE(note_id,tag_id),FOREIGN KEY(note_id,user_id) REFERENCES notes(id,user_id) ON DELETE CASCADE,FOREIGN KEY(tag_id,user_id) REFERENCES tags(id,user_id) ON DELETE CASCADE);
CREATE INDEX note_tags_note_id ON note_tags(note_id,user_id);
CREATE INDEX note_tags_tag_id ON note_tags(tag_id,user_id);
CREATE INDEX note_tags_updated ON note_tags(updated_at,id);
CREATE TRIGGER sync_note_tags_insert AFTER INSERT ON note_tags WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('note_tags',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'note_id',NEW.note_id,'tag_id',NEW.tag_id),(SELECT revision FROM native_sync_meta WHERE entity_table='note_tags' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='note_tags' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_note_tags_update AFTER UPDATE ON note_tags WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('note_tags',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'note_id',NEW.note_id,'tag_id',NEW.tag_id),(SELECT revision FROM native_sync_meta WHERE entity_table='note_tags' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='note_tags' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_note_tags_delete AFTER DELETE ON note_tags WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('note_tags',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='note_tags' AND id=OLD.id),OLD.remote_updated_at); END;
CREATE TABLE note_templates(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 300),content TEXT NOT NULL CHECK(length(content)<=1000000));
CREATE INDEX note_templates_updated ON note_templates(updated_at,id);
CREATE TRIGGER sync_note_templates_insert AFTER INSERT ON note_templates WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('note_templates',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'title',NEW.title,'content',NEW.content),(SELECT revision FROM native_sync_meta WHERE entity_table='note_templates' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='note_templates' AND id=NEW.id),NEW.remote_updated_at)); END;
