CREATE TRIGGER sync_note_templates_delete AFTER DELETE ON note_templates WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('note_templates',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='note_templates' AND id=OLD.id),OLD.remote_updated_at); END;
CREATE TABLE task_blocks(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),task_id TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,FOREIGN KEY(task_id,user_id) REFERENCES tasks(id,user_id) ON DELETE CASCADE,CHECK(julianday(end_at)>julianday(start_at)));
CREATE INDEX task_blocks_task_id ON task_blocks(task_id,user_id);
CREATE INDEX task_blocks_updated ON task_blocks(updated_at,id);
CREATE TRIGGER sync_task_blocks_insert AFTER INSERT ON task_blocks WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('task_blocks',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'task_id',NEW.task_id,'start_at',NEW.start_at,'end_at',NEW.end_at),(SELECT revision FROM native_sync_meta WHERE entity_table='task_blocks' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='task_blocks' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_task_blocks_update AFTER UPDATE ON task_blocks WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('task_blocks',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'task_id',NEW.task_id,'start_at',NEW.start_at,'end_at',NEW.end_at),(SELECT revision FROM native_sync_meta WHERE entity_table='task_blocks' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='task_blocks' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_task_blocks_delete AFTER DELETE ON task_blocks WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('task_blocks',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='task_blocks' AND id=OLD.id),OLD.remote_updated_at); END;
CREATE TABLE board_positions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),task_id TEXT NOT NULL UNIQUE,position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 2147483647),FOREIGN KEY(task_id,user_id) REFERENCES tasks(id,user_id) ON DELETE CASCADE,CHECK(id=task_id));
CREATE INDEX board_positions_task_id ON board_positions(task_id,user_id);
CREATE INDEX board_positions_updated ON board_positions(updated_at,id);
