CREATE TRIGGER sync_board_positions_update AFTER UPDATE ON board_positions WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('board_positions',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'task_id',NEW.task_id,'position',NEW.position),(SELECT revision FROM native_sync_meta WHERE entity_table='board_positions' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='board_positions' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_board_positions_delete AFTER DELETE ON board_positions WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('board_positions',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='board_positions' AND id=OLD.id),OLD.remote_updated_at); END;
